#[no_mangle]
pub extern "C" fn least_square_approx(v:*const i64,n:usize)->i64{if n<5||n>13||v.is_null(){return -1;}let a=unsafe{std::slice::from_raw_parts(v,n)};let k=a[0];if k<2||k>6||n!=1+2*k as usize{return -1;}let(mut sx,mut sy,mut sxx,mut sxy)=(0i64,0i64,0i64,0i64);for i in 0..k as usize{let(x,y)=(a[1+2*i],a[2+2*i]);if !(-20..=20).contains(&x)||!(-20..=20).contains(&y){return -1;}sx+=x;sy+=y;sxx+=x*x;sxy+=x*y;}let den=k*sxx-sx*sx;if den<=0{return -1;}let num=k*sxy-sx*sy;let rnd=|x:i64,d:i64|{let q=(x.abs()*100000+d/2)/d;if x<0{-q}else{q}};let(sl,it)=(rnd(num,den),rnd(sy*den-num*sx,k*den));let o=100000001i64;let r=200000003i64;if sl<=-o||sl>=o||it<=-o||it>=o{return -1;}(sl+o)*r+(it+o)}
